'use client';

import { useEffect, useState } from 'react';

import { useFormedible } from '@/hooks/use-formedible';
import { parseAiToFormedible } from '@/lib/formedible/ai-parser';
import type { AiFormParseResult, AiParserConfig } from '@/lib/formedible/ai-types';
import type { FormedibleFormValues, UseFormedibleOptions } from '@/lib/formedible/types';

export interface AiFormRendererProps {
  readonly code: string;
  readonly isStreaming?: boolean;
  readonly onParseComplete?: (result: AiFormParseResult) => void;
  readonly onSubmit?: (formData: FormedibleFormValues) => void | Promise<void>;
  readonly className?: string;
  readonly parserConfig?: AiParserConfig;
}

function EmptyForm({ className, message }: { readonly className?: string; readonly message: string }) {
  return <div className={className}>{message}</div>;
}

function ParsedForm({ className, options }: { readonly className?: string; readonly options: UseFormedibleOptions<FormedibleFormValues> }) {
  const { Form } = useFormedible(options);

  return <Form className={className} />;
}

export function AiFormRenderer({ code, isStreaming, onParseComplete, onSubmit, className, parserConfig }: AiFormRendererProps) {
  const [parseResult, setParseResult] = useState<AiFormParseResult>(() => parseAiToFormedible(code, parserConfig));

  useEffect(() => {
    if (isStreaming) {
      return;
    }

    const nextResult = parseAiToFormedible(code, parserConfig);
    setParseResult(nextResult);
    onParseComplete?.(nextResult);
  }, [code, isStreaming, onParseComplete, parserConfig]);

  if (isStreaming) {
    return <EmptyForm className={className} message="Waiting for the generated form..." />;
  }

  if (!parseResult.success) {
    return <EmptyForm className={className} message={parseResult.error ?? 'Generated form could not be parsed.'} />;
  }

  const options: UseFormedibleOptions<FormedibleFormValues> = {
    ...parseResult.formOptions,
    formOptions: {
      ...parseResult.formOptions.formOptions,
      onSubmit: async ({ value }) => {
        await parseResult.formOptions.formOptions.onSubmit?.({ value });
        await onSubmit?.(value);
      },
    },
  };

  return <ParsedForm className={className} options={options} />;
}

export { parseAiToFormedible } from '@/lib/formedible/ai-parser';
export type { AiFormParseResult, AiParserConfig } from '@/lib/formedible/ai-types';

'use client';

import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import type { AIProvider, ProviderSecrets, ProviderSettings } from '@/lib/formedible/ai-types';
import { cn } from '@/lib/utils';

export const providerOptions = [
  { value: 'openai', label: 'OpenAI', defaultModel: 'gpt-4o-mini', requiresKey: true },
  { value: 'anthropic', label: 'Anthropic', defaultModel: 'claude-sonnet-4-5', requiresKey: true },
  { value: 'openrouter', label: 'OpenRouter', defaultModel: 'openai/gpt-4o-mini', requiresKey: true },
] as const satisfies readonly { readonly value: AIProvider; readonly label: string; readonly defaultModel: string; readonly requiresKey: boolean }[];

export interface ProviderSelectionProps {
  readonly settings: ProviderSettings;
  readonly secrets: ProviderSecrets;
  readonly onChange: (settings: ProviderSettings, secrets: ProviderSecrets) => void;
  readonly className?: string;
}

export function createDefaultProviderSettings(provider: AIProvider = 'openai'): ProviderSettings {
  const option = providerOptions.find((entry) => entry.value === provider) ?? providerOptions[0];

  return {
    provider: option.value,
    model: option.defaultModel,
    temperature: 0.7,
    maxTokens: 4000,
  };
}

export function createDefaultProviderSecrets(provider: AIProvider = 'openai'): ProviderSecrets {
  return {
    provider,
    apiKey: '',
  };
}

export function validateProviderAccess(settings: ProviderSettings | null, secrets: ProviderSecrets | null): string | undefined {
  if (!settings) {
    return 'Provider settings are required.';
  }

  if (!secrets) {
    return 'Provider secrets are required.';
  }

  const provider = providerOptions.find((entry) => entry.value === settings.provider);

  if (!provider) {
    return 'Unsupported AI provider.';
  }

  if (settings.provider !== secrets.provider) {
    return 'Provider settings and secrets must target the same provider.';
  }

  if (provider.requiresKey && secrets.apiKey.trim().length === 0) {
    return `API key is required for ${provider.label}.`;
  }

  return undefined;
}

function isAIProvider(value: string | null): value is AIProvider {
  if (value === null) {
    return false;
  }

  return providerOptions.some((provider) => provider.value === value);
}

export function ProviderSelection({ settings, secrets, onChange, className }: ProviderSelectionProps) {
  return (
    <div className={cn('grid gap-3 rounded-lg border p-3', className)}>
      <label className="grid gap-1 text-sm font-medium">
        Provider
        <Select
          value={settings.provider}
          onValueChange={(providerValue) => {
            const provider = isAIProvider(providerValue) ? providerValue : providerOptions[0].value;
            const nextProvider = providerOptions.find((entry) => entry.value === provider) ?? providerOptions[0];
            onChange(createDefaultProviderSettings(nextProvider.value), { ...secrets, provider: nextProvider.value });
          }}
        >
          <SelectTrigger>
            <SelectValue placeholder="Select provider" />
          </SelectTrigger>
          <SelectContent>
            {providerOptions.map((provider) => (
              <SelectItem key={provider.value} value={provider.value}>
                {provider.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </label>
      <label className="grid gap-1 text-sm font-medium">
        Model
        <Input value={settings.model} onChange={(event) => onChange({ ...settings, model: event.target.value }, secrets)} />
      </label>
      <label className="grid gap-1 text-sm font-medium">
        API key
        <Input value={secrets.apiKey} type="password" onChange={(event) => onChange(settings, { ...secrets, apiKey: event.target.value })} />
      </label>
      <div className="grid gap-3 sm:grid-cols-2">
        <label className="grid gap-1 text-sm font-medium">
          Temperature
          <Input value={settings.temperature ?? ''} type="number" step="0.1" onChange={(event) => onChange({ ...settings, temperature: Number(event.target.value) }, secrets)} />
        </label>
        <label className="grid gap-1 text-sm font-medium">
          Max tokens
          <Input value={settings.maxTokens ?? ''} type="number" step="1" onChange={(event) => onChange({ ...settings, maxTokens: Number(event.target.value) }, secrets)} />
        </label>
      </div>
    </div>
  );
}

'use client';

import { chat } from '@tanstack/ai';
import type { ModelMessage, StreamChunk } from '@tanstack/ai';
import { useState } from 'react';

import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { validateProviderAccess } from '@/components/formedible/ai/provider-selection';
import { createTanStackTextAdapter } from '@/lib/formedible/ai-adapters';
import { extractFormCode } from '@/lib/formedible/ai-parser';
import type {
  AiGenerationRequest,
  AiGenerationResult,
  AiMessage,
  AIBuilderMode,
  ProviderSecrets,
  ProviderSettings,
} from '@/lib/formedible/ai-types';
import { cn } from '@/lib/utils';

export interface ChatInterfaceProps {
  readonly providerSettings: ProviderSettings | null;
  readonly providerSecrets: ProviderSecrets | null;
  readonly mode: AIBuilderMode;
  readonly messages: readonly AiMessage[];
  readonly onMessagesChange: (messages: readonly AiMessage[]) => void;
  readonly onFormGenerated?: (formCode: string) => void;
  readonly conversationId?: string;
  readonly systemPrompt?: string;
  readonly className?: string;
}

export const DEFAULT_AI_SYSTEM_PROMPT = 'You are Formedible AI Builder. Return a valid Formedible form configuration in a fenced formedible code block when generating or changing a form.';

function createMessage(role: AiMessage['role'], content: string, formCode?: string): AiMessage {
  return {
    id: `${role}-${Date.now()}-${Math.random().toString(36).slice(2)}`,
    role,
    content,
    formCode,
    timestamp: Date.now(),
  };
}

function toModelMessages(messages: readonly AiMessage[]): ModelMessage<string>[] {
  return messages
    .filter((message) => message.role !== 'system')
    .map((message) => ({ role: message.role === 'assistant' ? 'assistant' : 'user', content: message.content }));
}

function readTextChunk(chunk: StreamChunk): string {
  return 'delta' in chunk && typeof chunk.delta === 'string' ? chunk.delta : '';
}

async function requestAdapterGeneration(request: AiGenerationRequest): Promise<AiGenerationResult> {
  const validationError = validateProviderAccess(request.providerSettings, request.providerSecrets);

  if (validationError) {
    throw new Error(validationError);
  }

  const providerSettings = request.providerSettings;
  const providerSecrets = request.providerSecrets;

  if (!providerSettings || !providerSecrets) {
    throw new Error('Provider settings and secrets are required.');
  }

  const adapter = createTanStackTextAdapter(providerSettings, providerSecrets);
  let content = '';

  for await (const chunk of chat({
    adapter,
    messages: toModelMessages(request.messages),
    systemPrompts: [request.systemPrompt],
    temperature: providerSettings.temperature,
    maxTokens: providerSettings.maxTokens,
    conversationId: request.conversationId,
  })) {
    content += readTextChunk(chunk);
  }

  return { content, formCode: extractFormCode(content) };
}

export async function generateAiFormCode(
  request: AiGenerationRequest,
  mode: AIBuilderMode,
): Promise<AiGenerationResult> {
  if (mode === 'client') {
    return requestAdapterGeneration(request);
  }

  throw new Error('AI Builder requires client mode to generate a form.');
}

export function ChatInterface({
  providerSettings,
  providerSecrets,
  mode,
  messages,
  onMessagesChange,
  onFormGenerated,
  conversationId,
  systemPrompt = DEFAULT_AI_SYSTEM_PROMPT,
  className,
}: ChatInterfaceProps) {
  const [prompt, setPrompt] = useState('');
  const [error, setError] = useState<string>();
  const [isGenerating, setIsGenerating] = useState(false);

  async function submitPrompt() {
    const trimmedPrompt = prompt.trim();

    if (!trimmedPrompt || isGenerating) {
      return;
    }

    const userMessage = createMessage('user', trimmedPrompt);
    const nextMessages = [...messages, userMessage];
    onMessagesChange(nextMessages);
    setPrompt('');
    setError(undefined);
    setIsGenerating(true);

    try {
      const result = await generateAiFormCode(
        { prompt: trimmedPrompt, providerSettings, providerSecrets, messages: nextMessages, systemPrompt, userMessage, conversationId },
        mode,
      );
      const assistantMessage = createMessage('assistant', result.content, result.formCode);
      onMessagesChange([...nextMessages, assistantMessage]);

      if (result.formCode) {
        onFormGenerated?.(result.formCode);
      }
    } catch (generationError) {
      setError(generationError instanceof Error ? generationError.message : String(generationError));
      onMessagesChange(nextMessages);
    } finally {
      setIsGenerating(false);
    }
  }

  return (
    <div className={cn('flex h-full flex-col gap-3', className)}>
      <div className="min-h-0 flex-1 space-y-3 overflow-auto rounded-lg border p-3">
        {messages.length === 0 ? <p className="text-sm text-muted-foreground">Describe the form you want to build.</p> : null}
        {messages.map((message) => (
          <article key={message.id} className={cn('rounded-md p-3 text-sm', message.role === 'user' ? 'bg-muted' : 'border')}>
            <p className="mb-1 font-medium capitalize">{message.role}</p>
            <p className="whitespace-pre-wrap">{message.content}</p>
          </article>
        ))}
      </div>
      {error ? <p className="rounded-md border border-destructive/40 p-2 text-sm text-destructive">{error}</p> : null}
      <div className="grid gap-2">
        <Textarea value={prompt} onChange={(event) => setPrompt(event.target.value)} placeholder="Create a multi-step onboarding form..." />
        <Button type="button" disabled={isGenerating || prompt.trim().length === 0} onClick={submitPrompt}>
          {isGenerating ? 'Generating...' : 'Generate form'}
        </Button>
      </div>
    </div>
  );
}

export type { AiGenerationRequest, AiGenerationResult, AiMessage } from '@/lib/formedible/ai-types';

import type { AnyTextAdapter } from '@tanstack/ai';
import { createAnthropicChat } from '@tanstack/ai-anthropic';
import { createOpenaiChat } from '@tanstack/ai-openai';
import { createOpenRouterText } from '@tanstack/ai-openrouter';

import type { AIProvider, ProviderSecrets, ProviderSettings } from '@/lib/formedible/ai-types';

export type OpenAIAdapterModel = Parameters<typeof createOpenaiChat>[0];
export type AnthropicAdapterModel = Parameters<typeof createAnthropicChat>[0];
export type OpenRouterAdapterModel = Parameters<typeof createOpenRouterText>[0];

export const SUPPORTED_TANSTACK_AI_PROVIDERS = ['openai', 'anthropic', 'openrouter'] as const satisfies readonly AIProvider[];

export const DEFAULT_TANSTACK_AI_MODELS = {
  openai: 'gpt-4o-mini',
  anthropic: 'claude-sonnet-4-5',
  openrouter: 'openai/gpt-4o-mini',
} as const satisfies {
  readonly openai: OpenAIAdapterModel;
  readonly anthropic: AnthropicAdapterModel;
  readonly openrouter: OpenRouterAdapterModel;
};

function assertMatchingSecrets(settings: ProviderSettings, secrets: ProviderSecrets): void {
  if (settings.provider !== secrets.provider) {
    throw new Error('Provider settings and secrets must target the same provider.');
  }
}

export function createTanStackTextAdapter(settings: ProviderSettings, secrets: ProviderSecrets): AnyTextAdapter {
  assertMatchingSecrets(settings, secrets);

  if (settings.provider === 'openai') {
    return createOpenaiChat((settings.model || DEFAULT_TANSTACK_AI_MODELS.openai) as OpenAIAdapterModel, secrets.apiKey);
  }

  if (settings.provider === 'anthropic') {
    return createAnthropicChat((settings.model || DEFAULT_TANSTACK_AI_MODELS.anthropic) as AnthropicAdapterModel, secrets.apiKey);
  }

  return createOpenRouterText((settings.model || DEFAULT_TANSTACK_AI_MODELS.openrouter) as OpenRouterAdapterModel, secrets.apiKey);
}

import { FormedibleParser } from '@/lib/formedible/formedible-parser';
import type { AiFormParseResult, AiParserConfig } from '@/lib/formedible/ai-types';
import type { FormedibleFieldConfig, FormedibleFormValues, FormediblePageConfig, FormedibleProgressConfig, UseFormedibleOptions } from '@/lib/formedible/types';

const requiredFieldKeys = new Set(['name', 'type']);

function filterRecordKeys<TRecord extends Readonly<Record<string, unknown>>>(value: TRecord, allowedKeys: readonly string[] | undefined): Record<string, unknown> {
  if (!allowedKeys) {
    return { ...value };
  }

  const allowedKeySet = new Set(allowedKeys);
  return Object.fromEntries(Object.entries(value).filter(([key]) => allowedKeySet.has(key)));
}

function filterField(field: FormedibleFieldConfig<FormedibleFormValues>, parserConfig?: AiParserConfig): FormedibleFieldConfig<FormedibleFormValues> {
  if (parserConfig?.allowedFieldTypes && (field.type === undefined || !parserConfig.allowedFieldTypes.includes(field.type))) {
    throw new Error(`Field type '${field.type}' is not allowed.`);
  }

  if (!parserConfig?.allowedFieldKeys) {
    return field;
  }

  const allowedFieldKeys = new Set(parserConfig.allowedFieldKeys);
  return Object.fromEntries(Object.entries(field).filter(([key]) => requiredFieldKeys.has(key) || allowedFieldKeys.has(key))) as FormedibleFieldConfig<FormedibleFormValues>;
}

function filterPages(pages: readonly FormediblePageConfig<FormedibleFormValues>[] | undefined, parserConfig?: AiParserConfig): readonly FormediblePageConfig<FormedibleFormValues>[] | undefined {
  if (!pages || !parserConfig?.allowedPageKeys) {
    return pages;
  }

  return pages.map((page) => filterRecordKeys(page, parserConfig.allowedPageKeys) as FormediblePageConfig<FormedibleFormValues>);
}

function filterProgress(progress: FormedibleProgressConfig | undefined, parserConfig?: AiParserConfig): FormedibleProgressConfig | undefined {
  if (!progress || !parserConfig?.allowedProgressKeys) {
    return progress;
  }

  return filterRecordKeys(progress, parserConfig.allowedProgressKeys) as FormedibleProgressConfig;
}

function applyParserAllowlists(options: UseFormedibleOptions<FormedibleFormValues>, parserConfig?: AiParserConfig): UseFormedibleOptions<FormedibleFormValues> {
  const formOptions = filterRecordKeys(options.formOptions, parserConfig?.allowedFormOptionsKeys) as UseFormedibleOptions<FormedibleFormValues>['formOptions'];
  const output: Record<string, unknown> = {
    ...options,
    fields: options.fields.map((field) => filterField(field, parserConfig)),
    formOptions,
  };

  if (options.pages !== undefined) {
    output.pages = filterPages(options.pages, parserConfig);
  }

  if (options.progress !== undefined) {
    output.progress = filterProgress(options.progress, parserConfig);
  }

  if (parserConfig?.allowedKeys) {
    const allowedTopLevelKeys = new Set(parserConfig.allowedKeys);
    for (const key of Object.keys(output)) {
      if (key !== 'fields' && key !== 'formOptions' && !allowedTopLevelKeys.has(key)) {
        delete output[key];
      }
    }
  }

  return output as UseFormedibleOptions<FormedibleFormValues>;
}

function defaultValueForField(field: FormedibleFieldConfig<FormedibleFormValues>): unknown {
  if (field.type === 'checkbox' || field.type === 'switch') {
    return false;
  }

  if (field.type === 'number' || field.type === 'slider' || field.type === 'rating' || field.type === 'duration') {
    return 0;
  }

  if (field.type === 'multiSelect' || field.type === 'array') {
    return [];
  }

  if (field.type === 'object' || field.type === 'location') {
    return {};
  }

  return '';
}

function inferDefaultValues(options: UseFormedibleOptions<FormedibleFormValues>): UseFormedibleOptions<FormedibleFormValues> {
  const existingDefaults = options.formOptions.defaultValues;
  const defaultValues: FormedibleFormValues = { ...existingDefaults };

  for (const field of options.fields) {
    if (!Object.prototype.hasOwnProperty.call(defaultValues, field.name)) {
      defaultValues[field.name] = defaultValueForField(field);
    }
  }

  return {
    ...options,
    formOptions: {
      ...options.formOptions,
      defaultValues,
    },
  };
}

export function parseAiToFormedible(code: string, parserConfig?: AiParserConfig): AiFormParseResult {
  try {
    const parsed = FormedibleParser.parse(code, { strictValidation: parserConfig?.strictValidation ?? true });
    const allowedFormOptions = applyParserAllowlists(parsed, parserConfig);
    const formOptions = parserConfig?.inferDefaultValues === false ? allowedFormOptions : inferDefaultValues(allowedFormOptions);

    return {
      schema: formOptions.schema,
      formOptions,
      success: true,
    };
  } catch (error) {
    return {
      schema: undefined,
      formOptions: { fields: [], formOptions: { defaultValues: {} } },
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

export function extractFormCode(content: string): string | undefined {
  const formedibleBlock = content.match(/```(?:formedible|json|ts|tsx|typescript)?\s*([\s\S]*?fields\s*:[\s\S]*?)```/i);

  if (formedibleBlock?.[1]) {
    return formedibleBlock[1].trim();
  }

  const objectStart = content.indexOf('{');
  const fieldsIndex = content.indexOf('fields');
  const objectEnd = content.lastIndexOf('}');

  if (objectStart !== -1 && fieldsIndex > objectStart && objectEnd > fieldsIndex) {
    return content.slice(objectStart, objectEnd + 1).trim();
  }

  return undefined;
}

import type { ModelMessage } from '@tanstack/ai';

import type { AiMessage, AiMessageRole, AiMessageStatus, AiStreamEvent } from '@/lib/formedible/ai-types';

export type TanStackAiMessageInput = ModelMessage<string>;

export interface PersistedAiMessage {
  readonly id: string;
  readonly role: AiMessageRole;
  readonly content: string;
  readonly rawContent?: string;
  readonly thinking?: string;
  readonly formCode?: string;
  readonly timestamp?: number;
  readonly createdAt?: number;
  readonly updatedAt?: number;
  readonly provider?: AiMessage['provider'];
  readonly model?: string;
  readonly status?: AiMessageStatus;
  readonly events?: readonly AiStreamEvent[];
}

const AI_MESSAGE_ROLES = ['user', 'assistant', 'system'] as const satisfies readonly AiMessageRole[];
const AI_MESSAGE_STATUSES = ['idle', 'submitted', 'streaming', 'completed', 'error', 'aborted'] as const satisfies readonly AiMessageStatus[];

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isAiMessageRole(value: unknown): value is AiMessageRole {
  if (typeof value !== 'string') {
    return false;
  }

  return AI_MESSAGE_ROLES.some((role) => role === value);
}

function isAiMessageStatus(value: unknown): value is AiMessageStatus {
  if (typeof value !== 'string') {
    return false;
  }

  return AI_MESSAGE_STATUSES.some((status) => status === value);
}

function optionalString(value: unknown): string | undefined {
  return typeof value === 'string' ? value : undefined;
}

function optionalNumber(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function optionalStatus(value: unknown): AiMessageStatus | undefined {
  return isAiMessageStatus(value) ? value : undefined;
}

function toTanStackRole(role: AiMessageRole): 'user' | 'assistant' | undefined {
  if (role === 'system') {
    return undefined;
  }

  return role;
}

export function toTanStackMessageInput(message: Pick<AiMessage, 'role' | 'content'>): TanStackAiMessageInput | undefined {
  const role = toTanStackRole(message.role);

  if (!role) {
    return undefined;
  }

  return { role, content: message.content };
}

export function toTanStackMessageInputs(messages: readonly Pick<AiMessage, 'role' | 'content'>[]): TanStackAiMessageInput[] {
  return messages.flatMap((message) => {
    const input = toTanStackMessageInput(message);

    return input ? [input] : [];
  });
}

export function toTanStackSystemPrompts(messages: readonly Pick<AiMessage, 'role' | 'content'>[], explicitSystemPrompt?: string): string[] {
  const messagePrompts = messages
    .filter((message) => message.role === 'system' && message.content.trim().length > 0)
    .map((message) => message.content);

  if (explicitSystemPrompt === undefined || explicitSystemPrompt.trim().length === 0) {
    return messagePrompts;
  }

  return [explicitSystemPrompt, ...messagePrompts];
}

export function toPersistedAiMessage(message: AiMessage): PersistedAiMessage {
  return {
    id: message.id,
    role: message.role,
    content: message.content,
    rawContent: message.rawContent,
    thinking: message.thinking,
    formCode: message.formCode,
    timestamp: message.timestamp,
    createdAt: message.createdAt,
    updatedAt: message.updatedAt,
    provider: message.provider,
    model: message.model,
    status: message.status,
    events: message.events,
  };
}

export function normalizePersistedAiMessage(value: unknown): AiMessage | undefined {
  if (!isRecord(value) || typeof value.id !== 'string' || !isAiMessageRole(value.role) || typeof value.content !== 'string') {
    return undefined;
  }

  return {
    id: value.id,
    role: value.role,
    content: value.content,
    rawContent: optionalString(value.rawContent),
    thinking: optionalString(value.thinking),
    formCode: optionalString(value.formCode),
    timestamp: optionalNumber(value.timestamp),
    createdAt: optionalNumber(value.createdAt),
    updatedAt: optionalNumber(value.updatedAt),
    provider: value.provider === 'openai' || value.provider === 'anthropic' || value.provider === 'openrouter' ? value.provider : undefined,
    model: optionalString(value.model),
    status: optionalStatus(value.status),
  };
}

export function normalizePersistedAiMessages(values: unknown): AiMessage[] {
  if (!Array.isArray(values)) {
    return [];
  }

  return values.flatMap((value) => {
    const message = normalizePersistedAiMessage(value);

    return message ? [message] : [];
  });
}

